class Solution:
    def numberOfSubarrays(self, nums: List[int]) -> int:
        st = []
        ans = 0
        for x in nums:
            c = 1
            while st and st[-1][0] < x:
                st.pop()
            if st and st[-1][0] == x:
                c += st.pop()[1]
            st.append((x, c))
            ans += c
        return ans

