class Solution {
public:
    long long numberOfSubarrays(vector<int>& nums) {
        vector<pair<int, long long>> st;
        long long ans = 0;
        for (int x : nums) {
            long long c = 1;
            while (!st.empty() && st.back().first < x) st.pop_back();
            if (!st.empty() && st.back().first == x) c += st.back().second, st.pop_back();
            st.push_back({x, c});
            ans += c;
        }
        return ans;
    }
};

