class Solution {
    public long numberOfSubarrays(int[] nums) {
        Deque<long[]> st = new ArrayDeque<>();
        long ans = 0;
        for (int x : nums) {
            long c = 1;
            while (!st.isEmpty() && st.peek()[0] < x) st.pop();
            if (!st.isEmpty() && st.peek()[0] == x) c += st.pop()[1];
            st.push(new long[]{x, c});
            ans += c;
        }
        return ans;
    }
}

