class Solution:
    def numberOfSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            j = i
            while j >= 0 and nums[j] <= nums[i]:
                if nums[j] == nums[i]:
                    ans += 1
                j -= 1
        return ans

