class Solution {
public:
    long long numberOfSubarrays(vector<int>& nums) {
        int n = nums.size();
        long long ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = i; j >= 0 && nums[j] <= nums[i]; j--)
                if (nums[j] == nums[i]) ans++;
        return ans;
    }
};

